mapper.select:
SELECT sou_project.*
FROM scc_sou_project sou_project
WHERE sou_project.SOU_TYPE = 'ext_pur_inq'

    AND exists (
        SELECT * FROM scc_npm_sou_purinq_project inq_project
        WHERE inq_project.PROJECT_ID = sou_project.PROJECT_ID
        AND inq_project.DESIGN_PROJECT_CODE LIKE concat('%', concat(#{designProjectCode}, '%'))
    )


    AND sou_project.SOU_NO LIKE concat('%', concat(#{souNo}, '%'))


    AND sou_project.SOU_NAME LIKE concat('%', concat(#{souName}, '%'))


    AND sou_project.PROJECT_STATUS in ('ORDER_END', 'BUSINESS_EVAL', 'TECH_EVAL')


    AND sou_project.PROJECT_STATUS = #{extProjectStatus}


    AND sou_project.SCORE_RULE_TYPE = #{scoreRuleType}


    AND sou_project.CREATED_ID = #{createdId}


    AND sou_project.CREATED_BY LIKE concat('%', concat(#{createdBy}, '%'))


    AND sou_project.CREATE_APPROVAL_STATUS = #{createApprovalStatus}


    AND sou_project.CREATION_DATE >= #{creationDateFrom}


    AND sou_project.CREATION_DATE <= #{creationDateTo}


    AND sou_project.PUBLISH_TIME >= #{publishTimeFrom}


    AND sou_project.PUBLISH_TIME <= #{publishTimeTo}

ORDER BY sou_project.SOU_NO desc
